/** Removal is a soft delete so the audit log keeps pointing at a real row. */
export async function archiveMember(
  orgId: OrgId,
  memberId: MemberId,
): Promise<Member> {
  const row = getDb()
    .update(members)
    .set({ ...archivePatch(), status: "suspended" })
    .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
    .returning()
    .get();

  if (!row) throw new Error(`Member ${memberId} not found in org ${orgId}`);
  return toMember(row);
}

export async function touchLastSeen(
  orgId: OrgId,
  userId: UserId,
  at: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(members)
    .set({ lastSeenAt: at })
    .where(and(orgPredicate(members.orgId, orgId), eq(members.userId, userId)))
    .run();
}
/**
 * Query-time search plus the write-time index maintenance driven by `search.reindex_requested`.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, subscribe, isEnabled, consumeRateLimit
 */
import { subscribe } from "@/lib/event-bus";
import { isEnabled } from "@/lib/feature-flags";
import { assertCan } from "@/lib/permissions";
import { consumeRateLimit } from "@/lib/rate-limit";
import { assertOrgScope } from "@/lib/tenant";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import { orgResource } from "./_support";
import type { SearchQueryInput } from "@/schemas/search";
import type { SearchSubjectKind } from "@/server/repositories/search-repository";
import type { Comment } from "@/types/comment";
import type { OrgId, Page } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Issue } from "@/types/issue";
import type { Actor } from "@/types/member";
import type { Project } from "@/types/project";

export type SearchHit = {
  kind: SearchSubjectKind;
  id: string;
  title: string;
  snippet: string;
  href: string;
};

/** Characters of surrounding context kept on either side of a match. */
const SNIPPET_RADIUS = 60;

/** Token bucket protecting the index from query bursts. */
const SEARCH_QUERY_BUCKET = "search:query";

/**
 * Runs a query against the denormalised index. Field-scoped syntax
 * (`status:done`) is an `advanced_search` feature, so a query containing a
 * colon is rejected for plans that do not include it rather than silently
 * being treated as literal text.
 */
export async function search(
  actor: Actor,
  input: SearchQueryInput,
): Promise<Page<SearchHit>> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "issue:read", orgResource(input.orgId));

  const verdict = await consumeRateLimit(input.orgId, SEARCH_QUERY_BUCKET);
  if (!verdict.allowed) {
    throw new Error(
      `Search rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const org = await orgRepo.findOrgById(input.orgId);
  const advanced = isEnabled("advanced_search", {
    orgId: input.orgId,
    userId: actor.userId,
    plan: org?.plan ?? "free",
    role: actor.role,
    overrides: org?.settings.enabledFlagOverrides,
  });

  if (input.q.includes(":") && !advanced) {
    throw new Error("Field-scoped search is not included in this plan");
  }

  const page = await searchRepo.searchDocuments(input);

  return {
    items: page.items.map((row) => ({
      kind: row.subjectKind,
      id: row.subjectId,
      title: row.content.split("\n")[0] ?? row.subjectId,
      snippet: snippetAround(row.content, input.q),
      href: hrefFor(row.subjectKind, row.subjectId),
    })),
    nextCursor: page.nextCursor,
    total: page.total,
  };
}

export async function indexIssue(orgId: OrgId, issue: Issue): Promise<void> {
  await searchRepo.upsertSearchDocument(
    orgId,
    "issue",
    issue.id,
    [issue.title, issue.description ?? ""].join("\n"),
    issue.projectId,
  );
}

export async function indexComment(
  orgId: OrgId,
  comment: Comment,
): Promise<void> {
  await searchRepo.upsertSearchDocument(
    orgId,
    "comment",
    comment.id,
    comment.body,
    null,
  );
}

export async function indexProject(
  orgId: OrgId,
  project: Project,
): Promise<void> {
  await searchRepo.upsertSearchDocument(
    orgId,
    "project",
    project.id,
    [project.name, project.description ?? ""].join("\n"),
    project.id,
  );
}

export async function removeFromIndex(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
): Promise<void> {
  await searchRepo.deleteSearchDocument(orgId, subjectKind, subjectId);
}

/**
 * Keeps the index in step with writes. Every handler re-reads the row rather
 * than trusting the event payload, so a partially-applied write can never be
 * indexed as if it had succeeded.
 */
export function registerSearchListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.created", async (payload) => {
      const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
      if (issue) await indexIssue(payload.orgId, issue);
    }),
    subscribe("issue.updated", async (payload) => {
      const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
      if (issue) await indexIssue(payload.orgId, issue);
    }),
    subscribe("issue.archived", async (payload) => {
      await removeFromIndex(payload.orgId, "issue", payload.issueId);
    }),
    subscribe("comment.created", async (payload) => {
      const comment = await commentRepo.findCommentById(
        payload.orgId,
        payload.commentId,
      );
      if (comment) await indexComment(payload.orgId, comment);
    }),
    subscribe("comment.deleted", async (payload) => {
      await removeFromIndex(payload.orgId, "comment", payload.commentId);
    }),
    subscribe("project.created", async (payload) => {
      const project = await projectRepo.findProjectById(
        payload.orgId,
        payload.projectId,
      );
      if (project) await indexProject(payload.orgId, project);
    }),
    subscribe("project.archived", async (payload) => {
      await removeFromIndex(payload.orgId, "project", payload.projectId);
    }),
    subscribe("search.reindex_requested", async (payload) => {
      if (payload.subjectKind !== "issue") return;
      const issue = await issueRepo.findIssueById(
        payload.orgId,
        payload.subjectId as Issue["id"],
      );
      if (issue) await indexIssue(payload.orgId, issue);
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

function hrefFor(kind: SearchSubjectKind, subjectId: string): string {
  switch (kind) {
    case "issue":
      return `/issues/${subjectId}`;
    case "comment":
      return `/comments/${subjectId}`;
    case "project":
      return `/projects/${subjectId}`;
  }
}

function snippetAround(content: string, query: string): string {
  const at = content.toLowerCase().indexOf(query.toLowerCase());
  if (at < 0) return content.slice(0, SNIPPET_RADIUS * 2);

  const start = Math.max(0, at - SNIPPET_RADIUS);
  const end = Math.min(content.length, at + query.length + SNIPPET_RADIUS);
  return `${start > 0 ? "…" : ""}${content.slice(start, end)}${
    end < content.length ? "…" : ""
  }`;
}

/**
 * Token-bucket limiter applied to invites, comments, search and password
 * resets.
 *
 * Buckets are keyed by `(orgId, bucketKey)` and held in process — Taskflow
 * runs single-writer, and the corpus has no external cache. Capacity scales
 * with the org's plan through `getPlanLimits()`, so a growth org is not held
 * to a free org's ceiling; the per-bucket shape below is the base rate.
 */
import { getPlanLimits } from "@/config/plan-limits";
import type { PlanId } from "@/types/billing";
import type { IsoTimestamp, OrgId } from "@/types/common";
import { toIsoTimestamp } from "@/types/common";

export type RateLimitVerdict = {
  allowed: boolean;
  remaining: number;
  resetAt: IsoTimestamp;
};

export type RateLimitConfig = { capacity: number; refillPerMinute: number };

export const RATE_LIMIT_BUCKETS: Readonly<Record<string, RateLimitConfig>> = {
  "member:invite": { capacity: 20, refillPerMinute: 2 },
  "comment:create": { capacity: 60, refillPerMinute: 20 },
  "issue:create": { capacity: 60, refillPerMinute: 20 },
  "search:query": { capacity: 120, refillPerMinute: 60 },
  "auth:password-reset": { capacity: 5, refillPerMinute: 1 },
  "webhook:deliver": { capacity: 100, refillPerMinute: 50 },
};

/** Applied to any key not in the table above. */
const DEFAULT_BUCKET: RateLimitConfig = { capacity: 30, refillPerMinute: 10 };

type BucketState = { tokens: number; updatedAt: number };

const buckets = new Map<string, BucketState>();

/** Plan-aware org context; services set this when they know the org's plan. */
const planByOrg = new Map<OrgId, PlanId>();

/** Records an org's plan so subsequent bucket sizes scale with its quota. */
export function setOrgPlan(orgId: OrgId, plan: PlanId): void {
  planByOrg.set(orgId, plan);
}

export function getBucketConfig(bucketKey: string): RateLimitConfig {
  return RATE_LIMIT_BUCKETS[bucketKey] ?? DEFAULT_BUCKET;
}

/**
 * Scales the base bucket by the org's hourly API allowance, so the limiter
 * and the plan catalogue can never drift apart: the plan is the source of
 * the ceiling, this table only sets the relative shape.
 */
function configFor(orgId: OrgId, bucketKey: string): RateLimitConfig {
  const base = getBucketConfig(bucketKey);
  const plan = planByOrg.get(orgId) ?? "free";
  const hourly = getPlanLimits(plan).apiRequestsPerHour;
  const factor = Number.isFinite(hourly) ? Math.max(1, hourly / 100) : 100;

  return {
    capacity: Math.min(base.capacity * factor, base.capacity * 100),
    refillPerMinute: Math.min(
      base.refillPerMinute * factor,
      base.refillPerMinute * 100,
    ),
  };
}

/**
 * Spends `cost` tokens from the bucket, refilling first for the elapsed time.
 * Async because the production limiter is expected to move behind a store —
 * every call site already awaits it.
 */
export async function consumeRateLimit(
  orgId: OrgId,
  bucketKey: string,
  cost = 1,
): Promise<RateLimitVerdict> {
  const config = configFor(orgId, bucketKey);
  const key = `${orgId}:${bucketKey}`;
  const nowMs = Date.now();

  const state = buckets.get(key) ?? { tokens: config.capacity, updatedAt: nowMs };
  const elapsedMinutes = (nowMs - state.updatedAt) / 60_000;
  const tokens = Math.min(
    config.capacity,
    state.tokens + elapsedMinutes * config.refillPerMinute,
  );

  const allowed = tokens >= cost;
  const remaining = allowed ? tokens - cost : tokens;
  buckets.set(key, { tokens: remaining, updatedAt: nowMs });

  const deficit = allowed ? config.capacity - remaining : cost - remaining;
  const minutesToReset =
    config.refillPerMinute > 0 ? Math.max(0, deficit) / config.refillPerMinute : 0;

  return {
    allowed,
    remaining: Math.floor(remaining),
    resetAt: toIsoTimestamp(new Date(nowMs + minutesToReset * 60_000)),
  };
}

/** Test-only: drops every bucket and org plan association. */
export function resetRateLimits(): void {
  buckets.clear();
  planByOrg.clear();
}
import type {
  CommentId,
  IssueId,
  MemberId,
  OrgId,
  ProjectId,
  UserId,
  IsoTimestamp,
} from "./common";
import type { IssueStatus, IssuePriority } from "./issue";
import type { Role } from "./member";
import type { PlanId, LimitedResource } from "./billing";
import type { FeatureFlagKey } from "./feature-flag";

/** Fields present on every event payload; the bus stamps them on `emit`. */
export interface EventEnvelope {
  readonly orgId: OrgId;
  readonly actorId: UserId | null;
  readonly occurredAt: IsoTimestamp;
}

/**
 * The complete catalogue of domain events. `emit()` and `subscribe()` in
 * `src/lib/event-bus.ts` are keyed on this map, so adding an event here is the
 * only way to introduce one — services, jobs and the webhook dispatcher all
 * derive their handler signatures from it.
 */
export interface TaskflowEventMap {
  "project.created": EventEnvelope & {
    projectId: ProjectId;
    name: string;
    slug: string;
  };
  "project.archived": EventEnvelope & {
    projectId: ProjectId;
    issuesArchived: number;
  };
  "project.restored": EventEnvelope & { projectId: ProjectId };
  "issue.created": EventEnvelope & {
    issueId: IssueId;
    projectId: ProjectId;
    title: string;
    assigneeId: UserId | null;
    priority: IssuePriority;
  };
  "issue.updated": EventEnvelope & {
    issueId: IssueId;
    projectId: ProjectId;
    changedFields: readonly string[];
  };
  "issue.status_changed": EventEnvelope & {
    issueId: IssueId;
    projectId: ProjectId;
    from: IssueStatus;
    to: IssueStatus;
  };
  "issue.assigned": EventEnvelope & {
    issueId: IssueId;
    projectId: ProjectId;
    previousAssigneeId: UserId | null;
    assigneeId: UserId;
  };
  "issue.archived": EventEnvelope & { issueId: IssueId; projectId: ProjectId };
  "issue.overdue": EventEnvelope & {
    issueId: IssueId;
    projectId: ProjectId;
    dueAt: IsoTimestamp;
    assigneeId: UserId | null;
  };
  "comment.created": EventEnvelope & {
    commentId: CommentId;
    issueId: IssueId;
    mentionedUserIds: readonly UserId[];
  };
  "comment.deleted": EventEnvelope & { commentId: CommentId; issueId: IssueId };
  "member.invited": EventEnvelope & { email: string; role: Role };
  "member.joined": EventEnvelope & { memberId: MemberId; userId: UserId; role: Role };
  "member.role_changed": EventEnvelope & {
    memberId: MemberId;
    from: Role;
    to: Role;
  };
  "member.removed": EventEnvelope & { memberId: MemberId; userId: UserId };
  "billing.plan_changed": EventEnvelope & { from: PlanId; to: PlanId };
  "billing.limit_exceeded": EventEnvelope & {
    resource: LimitedResource;
    limit: number;
    used: number;
  };
  "flag.toggled": EventEnvelope & { flag: FeatureFlagKey; enabled: boolean };
  "digest.due": EventEnvelope & { recipientId: UserId; windowStart: IsoTimestamp };
  "search.reindex_requested": EventEnvelope & {
    subjectKind: "issue" | "comment" | "project";
    subjectId: string;
  };
  "webhook.delivery_requested": EventEnvelope & {
    eventType: string;
    payload: Readonly<Record<string, unknown>>;
  };
