export type TaskflowEventType = keyof TaskflowEventMap;

export type TaskflowEventPayload<K extends TaskflowEventType> =
  TaskflowEventMap[K];

/** A handler registered with `subscribe()`. May be async; errors are isolated. */
export type EventHandler<K extends TaskflowEventType> = (
  payload: TaskflowEventPayload<K>,
) => void | Promise<void>;

/** Returned by `subscribe()`; calling it removes the handler. */
export type Unsubscribe = () => void;
/**
 * One comment with author, timestamp and inline actions.
 *
 * Must call (do not reimplement): can
 */
import { Avatar } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/cn";
import { formatRelative } from "@/lib/date";
import { highlightMentions } from "@/lib/mentions";
import { can } from "@/lib/permissions";
import { isArchived } from "@/lib/soft-delete";
import type { CommentId } from "@/types/common";
import type { CommentWithAuthor } from "@/types/comment";
import type { Actor } from "@/types/member";
import type { ReactElement } from "react";
import { commentResource } from "../permission/resources";

export type CommentItemProps = {
  comment: CommentWithAuthor;
  actor: Actor;
  depth: number;
  onEdit?: (commentId: CommentId) => void;
  onDelete?: (commentId: CommentId) => void;
};

/** Replies are indented once; deeper nesting is flattened by the thread. */
const INDENT_REM = 2;

export function CommentItem(props: CommentItemProps): ReactElement | null {
  const { comment, actor, depth, onEdit, onDelete } = props;
  const resource = commentResource(comment);

  // Authors may edit and delete their own comments below the matrix rank —
  // that escalation lives in `can()`, not here.
  const mayEdit = can(actor, "comment:update", resource);
  const mayDelete = can(actor, "comment:delete", resource);

  if (isArchived(comment)) {
    return (
      <li className="text-sm italic text-neutral-500">
        This comment was deleted.
      </li>
    );
  }

  return (
    <li
      className={cn("comment-item flex gap-2 py-2")}
      style={{ marginLeft: `${Math.min(depth, 1) * INDENT_REM}rem` }}
    >
      <Avatar
        name={comment.author.name}
        src={comment.author.avatarUrl}
        size="sm"
      />

      <div className="min-w-0 flex-1">
        <p className="text-sm">
          <strong>{comment.author.name}</strong>
          <span className="ml-2 text-neutral-500">
            {formatRelative(comment.createdAt)}
          </span>
          {comment.editedAt !== null ? (
            <span className="ml-2 text-xs text-neutral-400">(edited)</span>
          ) : null}
        </p>

        <div
          className="mt-1 text-sm"
          dangerouslySetInnerHTML={{ __html: highlightMentions(comment.body) }}
        />

        {mayEdit || mayDelete ? (
          <div className="mt-1 flex gap-1">
            {mayEdit && onEdit !== undefined ? (
              <Button
                variant="ghost"
                size="sm"
                onClick={() => onEdit(comment.id)}
              >
                Edit
              </Button>
            ) : null}
            {mayDelete && onDelete !== undefined ? (
              <Button
                variant="ghost"
                size="sm"
                onClick={() => onDelete(comment.id)}
              >
                Delete
              </Button>
            ) : null}
          </div>
        ) : null}
      </div>
    </li>
  );
}
/**
 * Threaded comment list, hiding delete for non-authors.
 *
 * Must call (do not reimplement): can
 */
import { EmptyState } from "@/components/ui/empty-state";
import { can } from "@/lib/permissions";
import { isLive } from "@/lib/soft-delete";
import type { CommentId } from "@/types/common";
import type { CommentThreadNode } from "@/types/comment";
import type { Actor } from "@/types/member";
import type { ReactElement } from "react";
import { organizationResource } from "../permission/resources";
import { CommentItem } from "./comment-item";

export type CommentThreadProps = {
  nodes: readonly CommentThreadNode[];
  actor: Actor;
  onDelete: (commentId: CommentId) => void;
  onEdit?: (commentId: CommentId) => void;
};

/** Oldest first: a discussion reads top to bottom, unlike a feed. */
export function orderThread(
  nodes: readonly CommentThreadNode[],
): readonly CommentThreadNode[] {
  return [...nodes].sort((a, b) =>
    a.comment.createdAt.localeCompare(b.comment.createdAt),
  );
}

export function CommentThread(props: CommentThreadProps): ReactElement | null {
  const { nodes, actor, onDelete, onEdit } = props;

  if (!can(actor, "comment:read", organizationResource(actor.orgId))) {
    return null;
  }

  const visible = orderThread(nodes).filter((node) => isLive(node.comment));

  if (visible.length === 0) {
    return <EmptyState title="No comments yet" description="Start the thread." />;
  }

  return (
    <ol className="comment-thread divide-y">
      {visible.map((node) => (
        <li key={node.comment.id}>
          <ol>
            <CommentItem
              comment={node.comment}
              actor={actor}
              depth={0}
              onDelete={onDelete}
              {...(onEdit !== undefined ? { onEdit } : {})}
            />
            {node.replies
              .filter(isLive)
              .sort((a, b) => a.createdAt.localeCompare(b.createdAt))
              .map((reply) => (
                <CommentItem
                  key={reply.id}
                  comment={reply}
                  actor={actor}
                  depth={1}
                  onDelete={onDelete}
                  {...(onEdit !== undefined ? { onEdit } : {})}
                />
              ))}
          </ol>
        </li>
      ))}
    </ol>
  );
}
/**
 * Private paging helpers shared by the repositories in this directory.
 *
 * Not part of the public data-access surface — repositories re-export nothing
 * from here. Keyset (cursor) pagination is expressed as a row-value comparison
 * so a page boundary is stable even when two rows share a `created_at`.
 */
import { sql } from "drizzle-orm";
import { decodeCursor, encodeCursor } from "./base-repository";
import { makePage } from "@/types/common";
import type { Page } from "@/types/common";
import type { SQL } from "drizzle-orm";
import type { SQLiteColumn } from "drizzle-orm/sqlite-core";

export interface KeysetSort {
  readonly sortColumn: SQLiteColumn;
  readonly idColumn: SQLiteColumn;
}

/**
 * Predicate that resumes a descending listing after `cursor`. Returns
 * `undefined` for a first page or an unparseable cursor — a bad cursor
 * degrades to "start from the top", never to an error page.
 */
export function keysetPredicate(
  sort: KeysetSort,
  cursor: string | null | undefined,
): SQL | undefined {
  if (!cursor) return undefined;
  const decoded = decodeCursor(cursor);
  if (!decoded) return undefined;

  return sql`(${sort.sortColumn}, ${sort.idColumn}) < (${decoded.sortValue}, ${decoded.id})`;
}

/** SQLite tolerates a `LIMIT` of `n + 1`; that extra row is the has-more probe. */
export function probeLimit(limit: number): number {
  return Math.max(1, Math.min(limit, 100)) + 1;
}

/**
 * Turns an over-fetched row array into a `Page`, dropping the probe row and
 * deriving the next cursor from the last row that survived.
 */
export function toPage<TRow, TOut>(
  rows: readonly TRow[],
  limit: number,
  total: number,
  map: (row: TRow) => TOut,
  cursorOf: (row: TRow) => { id: string; sortValue: string },
): Page<TOut> {
  const capped = Math.max(1, Math.min(limit, 100));
  const hasMore = rows.length > capped;
  const visible = hasMore ? rows.slice(0, capped) : rows;
  const last = visible.at(-1);

  const nextCursor =
    hasMore && last
      ? encodeCursor(cursorOf(last).id, cursorOf(last).sortValue)
      : null;

  return makePage(visible.map(map), nextCursor, total);
}

/** Drops the `undefined` slots so `and(...)` never sees a hole. */
export function compact(
  ...predicates: readonly (SQL | undefined)[]
): readonly SQL[] {
  return predicates.filter((value): value is SQL => value !== undefined);
}

